window.OVA_CONTENT={"slug":"seccion-05-fisiologia-animal-y-gestion","title":"Fisiología animal y gestión productiva","minutes":40,"summary":"Interpreta digestión, respiración, circulación, metabolismo, bienestar y ambiente en sistemas ganaderos y avícolas.","objective":"Relacionar funciones fisiológicas con indicadores de manejo y desempeño animal.","stages":[{"eyebrow":"Sistemas","title":"1. Funciones que trabajan juntas","reading":"La digestión libera nutrientes; la respiración permite intercambio gaseoso; la circulación distribuye sustancias; el metabolismo integra reacciones de mantenimiento, crecimiento y producción.","application":"Un indicador productivo refleja la interacción entre sistemas, alimentación, ambiente, salud y manejo.","activity":{"type":"match","question":"Relaciona sistema y función principal.","pairs":[{"label":"Digestivo","value":"nutrientes","option":"Obtener nutrientes absorbibles"},{"label":"Respiratorio","value":"gases","option":"Intercambiar gases"},{"label":"Circulatorio","value":"distribuir","option":"Distribuir sustancias"}],"answer":["nutrientes","gases","distribuir"],"success":"Los sistemas se complementan."}},{"eyebrow":"Metabolismo","title":"2. Energía para mantener y producir","reading":"El organismo distribuye la energía disponible entre mantenimiento, actividad, termorregulación, crecimiento y producción. Si aumenta el costo de mantener la temperatura, puede disminuir la energía destinada al producto.","application":"La gestión debe interpretar consumo, conversión y producción junto con las condiciones ambientales.","activity":{"type":"choice","question":"Durante estrés térmico, ¿qué cambio es plausible?","options":["Más energía dedicada a termorregulación","Desaparición del metabolismo","Producción independiente del ambiente"],"answer":[0],"success":"El balance energético responde al ambiente."}},{"eyebrow":"Manejo","title":"3. Variables que modifican el desempeño","reading":"Calidad de dieta, acceso al agua, densidad, ventilación, temperatura, sanidad y bienestar influyen sobre el funcionamiento fisiológico. La especie y la etapa productiva cambian los rangos esperados.","application":"Comparar indicadores sin contexto puede llevar a decisiones erróneas.","activity":{"type":"multi","question":"Selecciona variables de manejo relevantes.","options":["Disponibilidad de agua","Ventilación","Densidad animal","Tipografía del informe"],"answer":[0,1,2],"success":"Las condiciones de manejo afectan la respuesta biológica."}},{"eyebrow":"Interpretación","title":"4. Del indicador a la decisión","reading":"Una baja en producción puede tener causas nutricionales, ambientales, sanitarias o de registro. Conviene verificar datos, observar patrones y solicitar valoración especializada cuando corresponda.","application":"La biología apoya la gestión, pero no sustituye el diagnóstico veterinario o zootécnico.","activity":{"type":"order","question":"Ordena un análisis prudente.","items":["Confirmar el indicador","Revisar ambiente y manejo","Comparar consumo y salud","Consultar valoración especializada","Aplicar y monitorear medidas"],"answer":[0,1,2,3,4],"success":"La decisión sigue evidencia y competencias profesionales."}},{"eyebrow":"Caso aplicado","title":"5. Galpón con alta temperatura","reading":"En un galpón aumentan la temperatura y la humedad, disminuye el consumo y baja la ganancia de peso. La ventilación funciona de manera irregular.","application":"La relación entre ambiente, termorregulación y consumo ofrece una hipótesis que debe verificarse.","activity":{"type":"choice","question":"¿Qué medida inicial es más coherente?","options":["Restablecer ventilación, medir condiciones y seguir indicadores","Cambiar la genética sin revisar el ambiente","Ignorar el consumo"],"answer":[0],"success":"Controlar y medir el ambiente permite evaluar la respuesta."}}],"number":"05","references":["Audesirk, T. et al. (2017). Biología: La vida en la tierra con fisiología. Pearson Educación.","Freeman, S. (2009). Biología. Pearson Educación.","Gutiérrez Ramírez, L. A. (2016). Los microorganismos en la agroindustria. Editorial Lasallista.","Mader, S. S. (2024). Biología. McGraw-Hill.","Velázquez Ocampo, M. P. (2020). Biología II. Cengage Learning."]};